     * or a transfer error.
     */
    @Throws(DspiException::class)
    fun setOutputPin(slot: Int, pin: Int)

    /**
     * Read the GPIO of physical output `slot` into `DspState.output_pins`
     * and return it.
     *
     * Errors: a transfer error (the device stalls on a slot it does not
     * have); [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchOutputPin(slot: Int): Int

    /**
     * Where the physical I/O configuration is stored: 0 = independently of
     * the presets (saved with [`DspiCore::save_output_config`]), 1 = with
     * each preset. A device-global flash write the firmware runs later.
     * Sets `DspState.output_config_mode`.
     *
     * Errors: [`DspiError::InvalidArgument`] for a mode above 1 (the
     * firmware would silently take it as 0); [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun setOutputConfigMode(mode: Int)

    /**
     * FLASH WRITE: persist the live physical I/O configuration (the
     * independent mode's explicit save). The firmware writes it later in
     * its main loop. Runs under the DSPi Link device lock: the deferred
     * flash write blacks out the device's control path for tens of
     * milliseconds, so other consoles must not interleave requests with it.
     *
     * Errors: [`DspiError::Refused`] with a `PRESET_*` status;
     * [`DspiError::Locked`] (Link); [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun saveOutputConfig()

    /**
     * On the demo device only, for clients' tests: how
     * [`save_output_config`](Self::save_output_config) answers from now on. 0 goes
     * through, 0xFF stalls, another byte is that status. `Unsupported`, with no
     * traffic, on anything but a simulated device.
     */
    @Throws(DspiException::class)
    fun demoOutputSaveStatus(status: Int)

    /**
     * The bus of output slot `slot` (a stereo pair, 0..4): 0 = S/PDIF,
     * 1 = I2S. The firmware switches later through a muted pipeline reset.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (no such slot)
     * or `INVALID_PIN` (a type above 1); [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun setOutputType(slot: Int, kind: Int)

    /**
     * The I2S bit-clock GPIO (the word clock is `pin + 1`). `role` 0 = the
     * master/shared pair, 1 = the slave pair used in split clock-pin mode.
     * `PIN_RESET_TO_DEFAULT` restores the role's default, read back.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (role above 1),
     * `INVALID_PIN`, `PIN_IN_USE` or `OUTPUT_ACTIVE` (I2S outputs run on
     * that pair); [`DspiError::ReadOnly`], [`DspiError::Disconnected`],
     * [`DspiError::Locked`] (Link, reset only) or a transfer error.
     */
    @Throws(DspiException::class)
    fun setI2sBckPin(role: Int, pin: Int)

    /**
     * 0 = master and slave share the clock pins (unified), 1 = separate
     * pairs (split).
     *
     * Errors: [`DspiError::Refused`] with `INVALID_PARAM` (mode above 1),
     * `OUTPUT_ACTIVE` (a live swap under running I2S outputs) or
     * `PIN_IN_USE` (the slave pair is taken); [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun setI2sClockPinMode(mode: Int)

    /**
     * The I2S master clock output on or off.
     *
     * Errors: [`DspiError::Refused`] with `PIN_IN_USE` (its pin was taken
     * meanwhile); [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setMckEnabled(enabled: Boolean)

    /**
     * The master clock GPIO (a clock-output-capable pin);
     * `PIN_RESET_TO_DEFAULT` restores the default, read back.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_PIN` (not a GPOUT pin),
     * `OUTPUT_ACTIVE` (MCK is enabled) or `PIN_IN_USE`;
     * [`DspiError::ReadOnly`], [`DspiError::Disconnected`],
     * [`DspiError::Locked`] (Link, reset only) or a transfer error.
     */
    @Throws(DspiException::class)
    fun setMckPin(pin: Int)

    /**
     * Master clock rate: 0 = 128 × fs, 1 = 256 × fs.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_PIN` for anything else;
     * [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a transfer
     * error.
     */
    @Throws(DspiException::class)
    fun setMckMultiplier(mult: Int)

    /**
     * The ADAT lightpipe output (RP2350) on or off.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (RP2040),
     * `INVALID_PARAM`, or `INVALID_PIN` / `PIN_IN_USE` (its pin, on
     * enabling); [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setAdatOutEnabled(enabled: Boolean)

    /**
     * The ADAT output GPIO; `PIN_RESET_TO_DEFAULT` restores the default,
     * read back. Allowed while enabled (the stream moves under mute).
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (RP2040),
     * `INVALID_PIN` or `PIN_IN_USE`; [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`], [`DspiError::Locked`] (Link, reset
     * only) or a transfer error.
     */
    @Throws(DspiException::class)
    fun setAdatOutPin(pin: Int)

    /**
     * The RX GPIO of S/PDIF input `index` (0..3); `PIN_RESET_TO_DEFAULT`
     * restores the default, read back. A disabled optional input stores
     * the pin as a preference; the live input is re-routed.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (no such input),
     * `INVALID_PIN` or `PIN_IN_USE`; [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`], [`DspiError::Locked`] (Link, reset
     * only) or a transfer error.
     */
    @Throws(DspiException::class)
    fun setSpdifRxPin(index: Int, pin: Int)

    /**
     * Enable or disable optional S/PDIF input `index` (1..3). Input 0 is
     * always on: enabling it is a no-op, disabling it is refused. Bit 0 of
     * `DspState.spdif_inputs_enabled` therefore always stays set.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (index 0 off, or
     * no such input) or `PIN_IN_USE` (enabling: its pin is invalid or
     * taken; disabling: it is the live source or a pending switch targets
     * it, so switch the source away first); [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun setSpdifInputEnabled(index: Int, enabled: Boolean)

    /**
     * The data GPIO of I2S input stereo pair `pair` (0..3);
     * `PIN_RESET_TO_DEFAULT` restores the default, read back.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (no such pair),
     * `INVALID_PIN` or `PIN_IN_USE`; [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`], [`DspiError::Locked`] (Link, reset
     * only) or a transfer error.
     */
    @Throws(DspiException::class)
    fun setI2sRxPin(pair: Int, pin: Int)

    /**
     * I2S input channels: 2, 4, 6 or 8 (four pairs on RP2350, one on
     * RP2040).
     *
     * Errors: [`DspiError::Refused`] with `INVALID_PIN` (not 2/4/6/8),
     * `INVALID_OUTPUT` (more pairs than the part has) or a pin status for a
     * newly active pair; [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun setI2sInputChannels(channels: Int)

    /**
     * The ADAT input (RP2350) on or off. Enabling needs a data pin
     * (`DspState.adat_input_pin` not 0xFF); only an enabled ADAT input can
     * be selected as the source.
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (RP2040),
     * `INVALID_PIN` (no pin set), or `PIN_IN_USE` (its pin is taken; or,
     * disabling, it is the live source: switch away first);
     * [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a transfer
     * error.
     */
    @Throws(DspiException::class)
    fun setAdatInputEnabled(enabled: Boolean)

    /**
     * The ADAT input GPIO; 0xFF clears it (allowed only while the input is
     * disabled). The ADAT output's pin is allowed (loopback self-test).
     *
     * Errors: [`DspiError::Refused`] with `INVALID_OUTPUT` (RP2040),
     * `INVALID_PIN` or `PIN_IN_USE` (taken, or clearing while enabled);
     * [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a transfer
     * error.
     */
    @Throws(DspiException::class)
    fun setAdatInputPin(pin: Int)

    /**
     * ADAT input clock: 0 = master (the device sets the rate), 1 = slave
     * (follows the lightpipe). Applied later in the firmware's main loop;
     * read the live mode back with [`DspiCore::fetch_input_lock`] (1).
     *
     * Errors: [`DspiError::Refused`] with `INVALID_PARAM` (above 1);
     * [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a transfer
     * error.
     */
    @Throws(DspiException::class)
    fun setAdatInputClockMode(mode: Int)

    /**
     * I2S/ADAT-master input rate: 0 = 44.1k, 1 = 48k, 2 = 96k (others clamp
     * to 48k). REQ_SET_INPUT_RATE 0xED is a payload SET with no status byte:
     * Ok means the transfer completed. The firmware stores the rate and
     * applies it live only while it is the rate authority (I2S or ADAT input
     * in master clock mode). Sets `DspState.i2s_input_rate`.
     *
     * Errors: [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setInputRate(index: Int)

    /**
     * Hz the pipeline runs at now (0 if unknown): the LIVE rate (firmware
     * `audio_state.freq`, REQ_GET_INPUT_RATE 0xEE word 0, same as status
     * wValue 15) for every source, not the configured I2S rate (word 1,
     * ignored; that one is `DspState.i2s_input_rate`).
     *
     * Errors: a reply shorter than 4 bytes or another transfer error;
     * [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchInputRate(): Long

    /**
     * I2S clock mode, 0 master / 1 slave. REQ_SET_I2S_CLOCK_MODE 0x88 is a
     * payload SET with no status byte (Ok = transfer completed); the
     * firmware applies it deferred in its main loop, and notifies then.
     * `DspState.i2s_clock_mode` holds the requested mode at once; the
     * firmware applies it later, and its notification brings the mirror to
     * the live mode.
     *
     * Errors: [`DspiError::InvalidArgument`] for a mode above 1 (the
     * firmware would ignore it silently); [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun setI2sClockMode(mode: Int)

    /**
     * Lock status of a clocked input. `which`: 0 = I2S slave
     * (`REQ_GET_I2S_SLAVE_STATUS`, 16 bytes; `rate_ok` is always true),
     * 1 = ADAT input (`REQ_GET_ADAT_INPUT_STATUS`, 20 bytes; all zero on
     * RP2040).
     *
     * Errors: [`DspiError::InvalidArgument`] for another `which`; a short
     * reply or other transfer error; [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchInputLock(which: Int): InputLockStatus

    /**
     * The ADAT output's status (8 bytes; all zero on RP2040).
     *
     * Errors: a short reply or other transfer error;
     * [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchAdatOutStatus(): AdatOutStatus

    /**
     * Send a DAC hardware mute config: on/off, polarity (`active_low`:
     * pull the pin low to mute), GPIO, and the hold times in ms around a
     * clock stop. The firmware validates and applies it later in its main
     * loop (with a flash write) and drops an invalid one silently: `Ok`
     * means only that the transfer completed. Read the outcome back with
     * [`DspiCore::fetch_dac_mute`] about 150 ms later; the mirror is not
     * changed here.
     *
     * Errors: [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setDacMute(enabled: Boolean, activeLow: Boolean, pin: Int, holdMs: Int, releaseMs: Int)

    /**
     * Re-read the DAC mute config into the state (`dac_mute_*`; also the
     * support probe: `dac_mute_supported` becomes true when it answers).
     *
     * Errors: a stall (firmware without the feature), a short reply or
     * another transfer error; [`DspiError::Disconnected`]. The mirror is
     * unchanged on error.
     */
    @Throws(DspiException::class)
    fun fetchDacMute()

    /**
     * Pulse the mute output for about a second, so an installer can hear
     * that the pin and polarity are right.
     *
     * Errors: [`DspiError::Refused`] { 3 } (`INVALID_OUTPUT`) when the DAC
     * mute is disabled; [`DspiError::ReadOnly`],
     * [`DspiError::Disconnected`] or a transfer error.
     */
    @Throws(DspiException::class)
    fun testDacMute()

    /**
     * LG Sound Sync on or off: live, saved with the preset. Sets
     * `DspState.lg_sound_sync_enabled`.
     *
     * Errors: [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setLgSoundSync(enabled: Boolean)

    /**
     * LG Sound Sync status: enabled, a TV detected, its last volume
     * (0..100, 0xFF before one is decoded) and mute.
     *
     * Errors: a short reply or other transfer error;
     * [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchLgStatus(): LgStatus

    /**
     * Re-read UART/I2C configs + status into the state (`uart`, `i2c`,
     * `ctrl_status`, `ctrl_iface_supported`). A device that does not
     * answer the status read has no control interfaces:
     * `ctrl_iface_supported` becomes false and the error is returned.
     *
     * Errors: a stall, a short reply or another transfer error;
     * [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchCtrlIfaces()

    /**
     * Send a UART control-interface config (pins, baud, notifications).
     * The firmware applies and persists it later; read the outcome
     * (`ctrl_status.uart_last_status`, a `PIN_CONFIG_*` code) with
     * [`DspiCore::fetch_ctrl_ifaces`] about 250 ms later. The mirror is not
     * changed here.
     *
     * Errors: [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setUart(config: UartConfig)

    /**
     * Send an I2C target control-interface config (pins, 7-bit address).
     * Applied and persisted later, as [`DspiCore::set_uart`]; read the
     * outcome with [`DspiCore::fetch_ctrl_ifaces`].
     *
     * Errors: [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    @Throws(DspiException::class)
    fun setI2c(config: I2cConfig)

    /**
     * Reboots the device into its USB bootloader (it disappears). Ok
     * whatever the transfer gives, as in the old core: the device drops off
     * the bus (also Ok without a device). Allowed on a read-only
     * connection, so a firmware too old or too new for this build can be
     * updated.
     *
     * The connection stays open until the departure is noticed (hotplug or
     * notifications). A firmware update then goes: this call; the
     * bootloader drive appears (`bootloader_drives`); `flash_to_drive`
     * writes the image; the DSPi re-enumerates. Only that last step
     * confirms success: open it again and check the new version with
     * [`DspiCore::firmware_version_matches`]; a timeout there is the
     * failure.
     *
     * The device lock is taken first and held across the restart (WP CG24),
     * so no other DSPi Link session writes to a device about to vanish; the
     * hub drops it when the device leaves. The connection's close gives it
     * back, and [`DspiCore::device_lock_release`] ends it when the install
     * ends otherwise (a restart that never happened); at most 60 s. A
     * refused lock sends nothing.
     *
     * Errors: [`DspiError::Locked`] / [`DspiError::Denied`] when the Link
     * hub refuses its lock; [`DspiError::Disconnected`] when the connection
     * changed while the hub was asked.
     */
    @Throws(DspiException::class)
    fun enterBootloader()

    /**
     * 0 idle, 1 PDM, 2 EQ worker. Also stored in `DspState.core1_mode`.
     *
     * Errors: a stall or other transfer error;
     * [`DspiError::Disconnected`].
     */
    @Throws(DspiException::class)
    fun fetchCore1Mode(): Int

    /**
     * Whether enabling `output` would conflict with Core 1's mode (PDM on
     * the last output and the Core 1 EQ worker exclude each other, and the
     * firmware skips a blocked enable silently). One `REQ_GET_CORE1_CONFLICT`
     * read; a failed read is an error, never "no conflict".
     *
     * Errors: [`DspiError::InvalidArgument`] for an output past the
     * device's output count (`DspState.num_output_channels`);
     * [`DspiError::Disconnected`] with no device; a stall, timeout or other
     * transfer error from the read.
     */
    @Throws(DspiException::class)
    fun checkCore1Conflict(output: Int): Boolean

    /**
     * Register (`Some`) or clear (`None`) the arrival/departure listener.
     * Clearing waits for a call in progress on another thread. The
     * listener is called on the thread that calls
     * [`DspiCore::poll_hotplug`], without the core's lock held; it may call
     * back into the core (`scan_devices`, `is_connected`), but must not set
     * listeners from inside the callback.
     */
    fun setHotplugCallback(listener: DeviceEvents?)

    /**
     * Compare the USB bus with the last poll and report arrivals and
     * departures (by serial) to the hotplug listener; reconnect the
     * selected device when it reappears, and close the open device when it
     * departs or its notification stream ends. Desktop apps call it about
     * every 500 ms; it enumerates without opening anything.
     *
     * **Poll off the UI thread.** A reconnect runs inside this call: the
     * whole connect sequence (the probe, the bulk read, the notification
     * reader's start) blocks the polling thread for that poll, a few hundred
     * milliseconds on a replug, and longer if the device answers slowly.
     * The listener calls and the reconnect both happen on this thread.
     *
     * Call [`DspiCore::scan_devices`] before the first poll: the first poll
     * diffs against that scan, so without one every unit present is
     * announced as arrived.
     *
     * Never fails: a failed reconnect is logged and retried on the next
     * polls (a few times). On Android there is nothing to enumerate (the
     * app gets USB broadcasts instead); there it only closes a connection
     * whose stream ended, and apps need not call it.
     */
    fun pollHotplug()

    /**
     * The user's name for input source `source` (`REQ_GET_INPUT_SOURCE_NAME`,
     * registry `in.name`); "" when unnamed.
     *
     * Errors: `Unsupported` on firmware without source names (nothing is
     * sent); `InvalidArgument` for a source the device does not have;
     * `Disconnected` without a device or before it was probed; `Transfer`
     * (or `Denied` / `Locked` over DSPi Link) when the read fails.
     */
    @Throws(DspiException::class)
    fun getInputSourceName(source: Int): String

    /**
     * Name input source `source` (`REQ_SET_INPUT_SOURCE_NAME`, registry
     * `in.name`); "" clears it. At most 31 bytes of UTF-8, no NUL. The
     * device stores it in flash from its main loop with a brief output
     * restart, then notifies `NOTIFY_EVT_INPUT_SOURCE_NAME`; a read right
     * after the write already returns the new name.
     *
     * Errors: `InvalidArgument` for a name that is too long or holds a NUL,
     * or a source the device does not have (nothing is sent); `ReadOnly` on
     * a read-only connection; `Unsupported` on firmware without source
     * names; `Disconnected`; `Transfer`, `Denied` or `Locked` from the link.
     */
    @Throws(DspiException::class)
    fun setInputSourceName(source: Int, name: String)

    /**
     * The device's own name (`REQ_GET_DEVICE_NAME`, registry `dev.name`), ""
     * when unnamed. Errors as for [`DspiCore::get_input_source_name`]
     * (`Unsupported` on firmware without device names).
     */
    @Throws(DspiException::class)
    fun getDeviceName(): String

    /**
     * Rename the device (`REQ_SET_DEVICE_NAME`, registry `dev.name`); ""
     * clears it. At most 31 bytes of UTF-8, no NUL; the front panel shows
     * only printable ASCII. Applied and notified (`NOTIFY_EVT_DEVICE_NAME`)
     * as a source name. Errors as for [`DspiCore::set_input_source_name`].
     */
    @Throws(DspiException::class)
    fun setDeviceName(name: String)

    /**
     * The name of input source `source` as last known, with no traffic: read
     * on connect, kept current by notifications (from any client) and by
     * [`DspiCore::set_input_source_name`], and read again after a lost
     * notification. "" when unnamed. For a client's rows, which would
     * otherwise read over the wire what connect has just read.
     *
     * Errors: `Unsupported` on firmware without source names; `InvalidArgument`
     * for a source past the table; `Disconnected` without a device or before
     * it was probed.
     */
    @Throws(DspiException::class)
    fun cachedInputSourceName(source: Int): String

    /**
     * The device's name as last known, with no traffic, kept as
     * [`DspiCore::cached_input_source_name`] keeps source names. "" when
     * unnamed. Errors: `Unsupported` on firmware without device names;
     * `Disconnected`.
     */
    @Throws(DspiException::class)
    fun cachedDeviceName(): String

    /**
     * Have someone else rename something on the demo device, for clients'
     * tests and demo mode: `target` is an input source, or 0xFF for the device
     * itself. The rename arrives as a notification that is not this client's
     * own. `Unsupported`, with no traffic, on anything but a simulated device.
     */
    @Throws(DspiException::class)
    fun demoRenameElsewhere(target: Int, name: String)

    /**
     * Set how the demo device applies an output-latency request, for clients'
     * tests: `mode` 0 at once (and a request held so far applies on the next
     * status read), 1 after `reads` status reads, 2 never, 3 dropped after
     * `reads` status reads. `blackout` status reads stall first while one is
     * pending, as the firmware's flash window does. `Unsupported`, with no
     * traffic, on anything but a simulated device; `InvalidArgument` for
     * another `mode`.
     */
    @Throws(DspiException::class)
    fun demoLatencyTiming(mode: Int, reads: Int, blackout: Int)

    /**
     * How many output-latency requests the demo device has received, for
     * clients' tests that a wait never sends one again. `Unsupported`, with no
     * traffic, on anything but a simulated device.
     */
    @Throws(DspiException::class)
    fun demoLatencySets(): Long

    /**
     * `REQ_OUTPUT_LATENCY` status (`wValue` 0, 12 bytes): the requested
     * and the effective option (a stream-only option requested while USB is
     * the source falls back to the first option without that flag), the
     * ring target in µs and frames, the batch in frames, `pending` (1 until
     * a SET has fully applied) and the option count, as `fields` in the
     * firmware's order.
     *
     * Errors: `Unsupported` on firmware without the setting (nothing is
     * sent); `Disconnected`; `Transfer` for a short or failed read.
     */
    @Throws(DspiException::class)
    fun fetchOutputLatency(): OutputLatency

    /**
     * The output-latency options (`REQ_OUTPUT_LATENCY` `wValue` 1), in the
     * firmware's order, with what choosing each gives on the active source
     * and rate (`effective_us`; a stream-only option on USB gives the
     * fallback's latency). A trailing partial entry is ignored.
     *
     * Errors as for [`DspiCore::fetch_output_latency`].
     */
    @Throws(DspiException::class)
    fun fetchOutputLatencyOptions(): List<OutputLatencyOption>

    /**
     * Request output-latency option `id` (`OutputLatencyId`, 1..=7: 0.67,
     * 1, 2, 3, 4, 6 and 8 ms; registry `out.latency`). The device applies
     * it from its main loop (a directory write and a synchronized output
     * restart): until then [`DspiCore::fetch_output_latency`] reports the
     * old `requested_id` with `pending` 1. A stream-only option (0.67 and
     * 1 ms) is stored as asked, but USB input runs the fallback.
     *
     * Errors: `InvalidArgument` for an id that is not an option (nothing is
     * sent); `ReadOnly` on a read-only connection; `Unsupported` on
     * firmware without the setting; `Disconnected`; `Transfer`, `Denied`
     * or `Locked` from the link.
     */
    @Throws(DspiException::class)
    fun setOutputLatency(id: Int)

    /**
     * `REQ_GET_CLOCK_DIAG` (0x82): the `ClockDiagPacket` (clock_diag.h)
     * latched by the firmware's 1 Hz poll, decoded into `fields` in packet
     * order (`slot_*[i]` per S/PDIF slot; `_cppm` are ppm × 100, `_mhz`
     * Hz × 1000, `_q16` Q16.16 samples per frame). Decoding stops at the
     * end of the reply, so an older packet version simply has fewer fields.
     *
     * `available` is false, with `raw` and `fields` empty, on firmware
     * built without `DSPI_CLOCK_DIAG` (a zero-length reply), when the
     * packet does not fit the transport, or on firmware without the
     * opcode (it stalls). Errors: `Disconnected`; `Transfer`, `Denied` or
     * `Locked` from the link.
     */
    @Throws(DspiException::class)
    fun fetchClockDiag(): ClockDiag

    /**
     * Open a DSPi Link session to `url` (`link_ws_url`), replacing any
     * previous one. `token` = the token stored for this hub's id ("" =
     * none). `expected_hub_id` = that id. With it, a token goes out only after
     * the hello has named that hub, and another hub at the address fails the
     * call with `wrong_hub`, having seen no token. "" = not known: the token
     * goes to whichever hub answers (a hub added by address, no stored id).
     * Blocks for the hello and authentication (up to ~15 s). When
     * `needs_pairing`, ask for the PIN and call `link_pair`; otherwise the
     * device list is ready (`link_devices`).
     *
     * From here on the core keeps the session up by itself: see
     * [`LinkListener`] and `link_status`. An app does not redial.
     *
     * Errors: [`DspiError::Link`], its `code` being `wrong_hub`, `io`, `handshake`,
     * `hub_busy` (all the hub's sessions are in use; try again in a few
     * seconds), `handshake_refused` (trying again will not help),
     * `rate_limited` (the token stays good; wait a minute), `protocol`,
     * `timeout`, `closed`, or the hub's own.
     */
    @Throws(DspiException::class)
    fun linkConnect(url: String, clientName: String, appVersion: String, token: String, expectedHubId: String): LinkHello

    /**
     * Pair with the PIN the user typed (role `control`, as the macOS
     * Console asks). Returns the token to store against the hub id ("" when
     * the hub issued none). If the hub dropped the socket while the prompt
     * was up (its 30 s auth deadline), it is dialled again first. A pairing
     * succeeds even if the device list then fails; the core reads it again.
     *
     * Errors, as [`DspiError::Link`] with `msg` ready to show:
     * - `wrong_pin`: a wrong PIN, or, on a hub showing its PIN in a window,
     * one that is wrong or expired, or a closed window (the hub does not
     * say which). Ask again;
     * - `rate_limited`: too many wrong tries; the hub refuses for a minute;
     * - `timeout`: no answer. The hub may still have accepted the PIN:
     * [`LinkListener::on_link_token_issued`] then still delivers the token;
     * - anything else [`DspiCore::link_connect`] reports;
     * - [`DspiError::Disconnected`] with no session.
     */
    @Throws(DspiException::class)
    fun linkPair(pin: String): String

    /**
     * The hub's devices (empty before authentication).
     */
    fun linkDevices(): List<LinkDevice>

    /**
     * Where the session stands; [`LinkStatus::phase`] is what to tell the
     * user. No blocking beyond the core lock.
     */
    fun linkStatus(): LinkStatus

    /**
     * Bind the core to the hub's device `handle` (as `open_fd` does for
     * USB): starts the notify listener over Link, resets the state. Then
     * `fetch_all` as usual (single-shot bulk, the hub's snapshot first).
     * Selecting again uses the same hub session and slot.
     *
     * The core binds it again by itself after a reconnect, and when the
     * hub lists it online again, unless the app called `disconnect` while
     * the session was up. `disconnect` while reconnecting does not stop
     * that: `link_close` does.
     *
     * Opening another device over the bound one closes the hub session. After `disconnect` the session stays, ready
     * for another `link_select_device`, and keeps its slot: call
     * `link_close` when leaving the hub.
     *
     * Errors: [`DspiError::InvalidArgument`] for a handle over 255 (they
     * are one byte on the wire); [`DspiError::Disconnected`] when the
     * session is not ready; as for the connect sequence.
     */
    @Throws(DspiException::class)
    fun linkSelectDevice(handle: Long, serial: String)

    /**
     * Close the Link session (normal close) and drop a device bound to it,
     * and stop any reconnecting. This is how an app leaves a hub, giving back
     * its session slot (`disconnect` keeps the session, for another
     * `link_select_device`), and it is the banner's abort button.
     *
     * Safe on a UI thread: it returns within about 100 ms whatever the link
     * does, and `link_status` then says [`LinkPhase::Idle`]. It does not need
     * the core lock, and ends a command stuck on a stalled link. On a healthy
     * link the device is closed when it returns; on a stalled one that
     * finishes behind it. A dial in progress is thrown away. A USB device open
     * meanwhile stays open. Quiet: no `on_link_closed`.
     */
    fun linkClose()

    /**
     * Register (`Some`) or clear (`None`) the session events listener. Same
     * rules as the other listeners: called with the core lock released, and
     * clearing waits for a call in progress.
     */
    fun setLinkListener(listener: LinkListener?)

    /**
     * Try to reconnect now instead of waiting out the backoff (the platform
     * says the network is back). A no-op unless reconnecting.
     */
    fun linkRetryNow()

    /**
     * The hub answers at a new address (the app's browser found its `hid`
     * again after a DHCP change): reconnect there from now on, at once if
     * reconnecting. The core does not browse by itself.
     *
     * An address that cannot be dialled is logged and ignored: reconnecting
     * to it would fail for ever.
     */
    fun linkSetUrl(url: String)

    /**
     * The log entries recorded after `after_id`, oldest first, and the id
     * to pass next time (`after_id` itself when there are none). Pass 0
     * for everything still held. Entries are recorded when
     * [`DspiCore::process_notifications`] drains the queue. Never fails.
     */
    fun monitorRead(afterId: Long): MonitorBatch

    /**
     * Forget the logged entries. Ids are not reused: a reader's last id
     * stays valid.
     */
    fun monitorClear()

    /**
     * Register (`Some`) or clear (`None`) the wake-up listener of the
     * notification reader. It is called on the reader thread whenever a
     * packet was queued (and once when the stream ends), and must only
     * schedule a call to [`DspiCore::process_notifications`].
     *
     * Setting or clearing waits for a call in progress on another thread,
     * so after `None` returns the old listener is not running. Never call
     * this from inside the listener itself (it would wait for itself).
     */
    fun setNotifyListener(listener: NotifyListener?)

    /**
     * Apply every queued notification to the mirror and say what changed:
     * `flags` are the `NOTIFY_*` bits (`crate::consts`), `filter_channels`
     * a bit per wire channel whose PEQ or crossover bands changed.
     *
     * - A parameter another host (a knob, the OS volume, UART, MIDI, ...)
     * changed is patched into the mirror: `NOTIFY_STATE`, plus
     * `NOTIFY_CURVES` when it moves the graph.
     * - Our own echoes are applied silently, unless the device's value
     * differs from the mirror's (then they are reported like a foreign
     * change).
     * - A foreign bulk write, a preset load, lost packets or a change the
     * mirror cannot patch re-read the whole image and the preset
     * directory: `NOTIFY_STATE | NOTIFY_CURVES | NOTIFY_REFRESHED`. A
     * preset load or factory reset also makes the new state the
     * baseline of `preset_dirty`. If the re-read fails, the flags say
     * only what was patched, and it is tried again: up to 5 times over
     * about 31 s, each try announced by a call of the [`NotifyListener`].
     * After the last one the result carries [`NOTIFY_STALE`], once; the
     * next change that needs a re-read starts over.
     * - `NOTIFY_DISCONNECTED`: the stream ended because the device went
     * away (never after an intentional close). It is reported on every
     * call until the connection is closed; the caller should close it
     * (`disconnect`, or C1b's hotplug handling). A lost DSPi Link session
     * does not count while the core is reconnecting (`link_status`):
     * leave the connection alone, and the mirror stays last known.
     *
     * Every packet is also recorded in the monitor log
     * ([`DspiCore::monitor_read`]).
     *
     * Without a device, or with nothing queued, it returns an empty
     * result. Never fails and never panics on device data. Blocks only
     * for a re-read (one bulk read and the directory read, plus the input
     * source names after a lost packet).
     */
    fun processNotifications(): NotifyResult

    /**
     * PEQ band 0..9 of wire channel `ch`, sent as one whole band
     * (`REQ_SET_EQ_PARAM`).
     *
     * The gain is quantized to 0.1 dB, except on a Linkwitz Transform, where
     * it carries the target frequency fp in Hz. A Linkwitz Transform's
     * target Q `qp` is clamped to 0.1..20; other types ignore `qp` (the
     * mirror reads it back as 0.707).
     *
     * Errors: [`DspiError::InvalidArgument`] for a channel or band out of
     * range, a non-finite frequency, Q or gain, or a NaN `qp` on a
     * Linkwitz Transform; the connection and transfer errors of every
     * setter ([`DspiError::Disconnected`], [`DspiError::ReadOnly`],
     * [`DspiError::Transfer`]).
     */
    @Throws(DspiException::class)
    fun setFilter(ch: Int, band: Int, params: FilterParams)

    /**
     * Crossover band 0..3 of an output's wire channel `ch` (wire band
     * `20 + xband`). The type must be flat (0) or a crossover type (32..63);
     * the gain is sent as given.
     *
     * Errors: [`DspiError::InvalidArgument`] for an input channel, a band
     * out of range, another filter type or a non-finite value; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossover(ch: Int, xband: Int, params: FilterParams)

    /**
     * Bypass (`true`) or re-enable one band of wire channel `ch`, keeping
     * its settings (`REQ_SET_BAND_BYPASS`). `band`: PEQ 0..9, or crossover
     * 20..23 on an output channel.
     *
     * Errors: [`DspiError::InvalidArgument`] for a channel or band out of
     * range; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setBandBypass(ch: Int, band: Int, bypass: Boolean)

    /**
     * Legacy preamp: every input to the same value (`REQ_SET_PREAMP`), in
     * dB, clamped to −60..[`DspiCore::preamp_max_db`] and quantized to
     * 0.1 dB.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setPreamp(db: Float)

    /**
     * Preamp of one input (`REQ_SET_PREAMP_CH`), in dB, clamped to
     * −60..[`DspiCore::preamp_max_db`] and quantized to 0.1 dB. Input 0 is
     * also the legacy `preamp_db`.
     *
     * Errors: [`DspiError::InvalidArgument`] for an input out of range or a
     * NaN; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setInputPreamp(input: Int, db: Float)

    /**
     * Bypass the whole EQ (`true`) or run it.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setBypass(enabled: Boolean)

    /**
     * Device master volume in dB: −128 (or anything below) mutes, otherwise
     * −127..0 in 0.5 dB steps (rounded, then clamped).
     *
     * The firmware answers with the legacy v1 volume notification and then
     * a `PARAM_CHANGED`; both are the echo of this write.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setMasterVolume(db: Float)

    /**
     * 0 = master volume independent of presets, 1 = saved with presets.
     *
     * Errors: [`DspiError::InvalidArgument`] for another mode; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setMasterVolumeMode(mode: Int)

    /**
     * FLASH WRITE: store the live master volume for the independent mode
     * (`REQ_SAVE_MASTER_VOLUME`). Changes nothing in the mirror.
     *
     * Errors: [`DspiError::Refused`] with the device's status byte
     * (`PRESET_*`) when the save fails; the connection and transfer errors
     * of every setter.
     */
    @Throws(DspiException::class)
    fun saveMasterVolume()

    /**
     * User volume (what the host's volume slider drives) in dB, clamped to
     * −60..0.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setUserVolume(db: Float)

    /**
     * Mute (`true`) or unmute the user volume.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setUserMute(muted: Boolean)

    /**
     * Delay of wire channel `ch` in ms, quantized to 0.0001 ms and then
     * clamped to 0..[`DspiCore::max_delay_ms`]. An output channel's delay
     * is its output delay, so it goes through [`DspiCore::set_output_delay`].
     *
     * Errors: [`DspiError::InvalidArgument`] for a channel out of range or a
     * NaN; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setDelay(ch: Int, ms: Float)

    /**
     * Loudness compensation on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLoudness(enabled: Boolean)

    /**
     * Loudness reference level in dB SPL, clamped to 40..100 as the
     * firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLoudnessRef(spl: Float)

    /**
     * Loudness intensity in percent, clamped to 0..200 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLoudnessIntensity(pct: Float)

    /**
     * Bit k: loudness compensates output k.
     *
     * Errors: [`DspiError::Unsupported`] on firmware without the per-output
     * mask; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLoudnessMask(mask: Int)

    /**
     * Crossfeed on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossfeed(enabled: Boolean)

    /**
     * Crossfeed preset: 0 default, 1 Chu Moy, 2 Meier, 3 custom. Only the
     * preset changes: `crossfeed_freq` and `crossfeed_feed` are the device's
     * custom values, which it keeps whatever the preset.
     *
     * Errors: [`DspiError::InvalidArgument`] for another preset; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossfeedPreset(preset: Int)

    /**
     * Custom crossfeed frequency in Hz, clamped to 500..2000 as the firmware
     * does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossfeedFreq(freq: Float)

    /**
     * Custom crossfeed feed level in dB, clamped to 0..15 as the firmware
     * does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossfeedFeed(feed: Float)

    /**
     * Crossfeed interaural time delay on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossfeedItd(enabled: Boolean)

    /**
     * Bit p: crossfeed runs on output pair p. The firmware keeps only the
     * bits of pairs it has; its echo corrects the mirror.
     *
     * Errors: [`DspiError::Unsupported`] on firmware without the mask; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setCrossfeedOutputs(pairMask: Int)

    /**
     * Volume leveller on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerEnabled(enabled: Boolean)

    /**
     * Leveller amount in percent, clamped to 0..100 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerAmount(pct: Float)

    /**
     * 0 slow, 1 medium, 2 fast.
     *
     * Errors: [`DspiError::InvalidArgument`] for another speed; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerSpeed(speed: Int)

    /**
     * Leveller maximum gain in dB, clamped to 0..35 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerMaxGain(db: Float)

    /**
     * Leveller look-ahead on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerLookahead(enabled: Boolean)

    /**
     * Leveller gate threshold in dB, clamped to −96..0 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerGate(db: Float)

    /**
     * Leveller detector and apply masks (bit k: output k).
     *
     * Errors: [`DspiError::Unsupported`] on firmware without the masks; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerMasks(detector: Int, apply: Int)

    /**
     * Input source: 0 USB, 1 S/PDIF, 2 I2S, 3 ADAT, 4..6 S/PDIF inputs 2..4.
     * The firmware switches on its main loop and ignores a source that is
     * not selectable (a disabled S/PDIF input); its notification at the
     * switch, or a re-read, corrects the mirror.
     *
     * Errors: [`DspiError::InvalidArgument`] above 6; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setInputSource(source: Int)

    /**
     * One matrix crosspoint: route `input` to `output`, with a gain in dB
     * (quantized to 0.1 dB) and polarity.
     *
     * Errors: [`DspiError::InvalidArgument`] for an input or output out of
     * range or a non-finite gain; the connection and transfer errors of
     * every setter.
     */
    @Throws(DspiException::class)
    fun setMatrixRoute(input: Int, output: Int, enabled: Boolean, gain: Float, invert: Boolean)

    /**
     * Enable or disable an output. Returns the resulting state, read back
     * from the device: the firmware silently refuses an enable that would
     * collide on Core 1 (PDM against the EQ-worker outputs). An enable is
     * checked first (`REQ_GET_CORE1_CONFLICT`) and not sent when it would
     * collide. The Core 1 mode is re-read afterwards when the device
     * answers it.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range; the
     * connection and transfer errors of every setter. A failed read-back is
     * not an error: the requested state (or, after a refused enable, the
     * previous one) is assumed, as the old core did.
     */
    @Throws(DspiException::class)
    fun setOutputEnable(output: Int, enabled: Boolean): Boolean

    /**
     * Output gain in dB, clamped to −60..+20 and quantized to 0.1 dB.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range or
     * a NaN; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setOutputGain(output: Int, db: Float)

    /**
     * Mute (`true`) or unmute one output.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setOutputMute(output: Int, muted: Boolean)

    /**
     * Output delay in ms, quantized to 0.0001 ms and then clamped to
     * 0..[`DspiCore::max_delay_ms`]. It is also the delay of the output's
     * wire channel.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range or
     * a NaN; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setOutputDelay(output: Int, ms: Float)

    /**
     * Name of wire channel `ch`, cut to 31 bytes on a character boundary
     * (the firmware keeps 31 and a NUL).
     *
     * Errors: [`DspiError::InvalidArgument`] for a channel out of range; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setChannelName(ch: Int, name: String)

    /**
     * Reads the name of wire channel `ch` from the device
     * (`REQ_GET_CHANNEL_NAME`) and keeps it in the mirror. Works on a
     * read-only connection too (its image is then left alone).
     *
     * Errors: [`DspiError::Disconnected`] with no device;
     * [`DspiError::InvalidArgument`] for a channel out of range; the
     * transfer's error.
     */
    @Throws(DspiException::class)
    fun getChannelName(ch: Int): String

    /**
     * Set one psychoacoustic-bass parameter. `param`: `PSYBASS_PARAM_*`
     * (cutoff Hz 30..300, harmonics dB -24..12, drive dB 0..18, character %
     * 0..100, original dB -60..0); the value is clamped to that range.
     *
     * Errors: `InvalidArgument` (unknown `param`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no psychoacoustic bass), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setPsybassParam(param: Int, value: Float)

    /**
     * Which outputs psychoacoustic bass processes: bit k = output k.
     *
     * Errors: `Disconnected`, `ReadOnly`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun setPsybassMask(mask: Int)

    /**
     * Turn psychoacoustic bass on or off.
     *
     * Errors: `Disconnected`, `ReadOnly`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun setPsybassEnabled(enabled: Boolean)

    /**
     * Set one output-limiter parameter of `output` (0-based), or of every
     * output when `output` is `LIMITER_ALL_OUTPUTS` (0xFF). `param`:
     * `LIMITER_PARAM_*` (enabled: non-zero is on; threshold dB -30..0;
     * release ms 10..1000; link group 0..4, 0 = unlinked), clamped as the
     * firmware does. The mirror follows the firmware's link groups: a write
     * to one member moves the whole group, joining a group adopts its
     * settings, and a group set on every output gangs each group to its
     * lowest member.
     *
     * Errors: `InvalidArgument` (unknown `param`, NaN, an output past the
     * device's), `Disconnected`, `ReadOnly`, `Unsupported` (no limiter),
     * `Transfer`.
     */
    @Throws(DspiException::class)
    fun setLimiterParam(output: Int, param: Int, value: Float)

    /**
     * Gain reduction per output in dB (positive while limiting, 120 = the
     * display floor), [`MAX_OUTPUTS`] entries; outputs the device does not
     * have read 0. Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Unsupported` (no limiter), `Transfer`
     * (including a short reply).
     */
    @Throws(DspiException::class)
    fun fetchLimiterMeter(): List<Float>

    /**
     * Set upmixer parameter `id` (`UPMIX_PARAM_*`); RP2350 only. The value
     * is clamped to the firmware's range; the enable and the modes are
     * rounded (an out-of-range centre mode becomes adaptive, as the
     * firmware does), the presence goes in 0.5 dB steps.
     *
     * Errors: `InvalidArgument` (unknown `id`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (RP2040), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setUpmixParam(id: Int, value: Float)

    /**
     * The upmixer's live state: active, why it is parked, correlation and
     * balance (-1..1, 0..1), and the centre and surround gains (0..1). All
     * zero on an RP2040. Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Transfer` (including a reply under 12
     * bytes).
     */
    @Throws(DspiException::class)
    fun fetchUpmixStatus(): UpmixStatus

    /**
     * Set subharmonic-synth parameter `id` (`SUBHARM_PARAM_*`), clamped to
     * its range; the flags, the mask and the selectivity mode are rounded.
     *
     * Errors: `InvalidArgument` (unknown `id`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no subharmonic synth), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setSubharmParam(id: Int, value: Float)

    /**
     * Mute the program on the subharm outputs so the synthesized sub is
     * heard alone. Monitoring only: never saved, not in the bulk image.
     *
     * Errors: `Disconnected`, `ReadOnly`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun setSubharmSolo(solo: Boolean)

    /**
     * How far the current subharm settings can push the signal above its
     * input, dB (computed by the device). Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun fetchSubharmHeadroom(): Float

    /**
     * Decaying peak of the synthesized sub per output, 0..1,
     * [`MAX_OUTPUTS`] entries; outputs the device does not have read 0.
     * Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun fetchSubharmMeter(): List<Float>

    /**
     * Set tube-preamp parameter `idx` (`TUBE_PARAM_*`), clamped to its
     * range; the flags, the mask, the type and the rectifier are rounded.
     * The mirror follows the firmware: choosing a type 1..16 loads its
     * bias, asymmetry, hardness and sag; changing one of those four drops
     * the type to Custom (0).
     *
     * Errors: `InvalidArgument` (unknown `idx`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no tube preamp), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setTubeParam(idx: Int, value: Float)

    /**
     * Save the live state to preset `slot` (0..10) and make it the active
     * slot. **Writes flash.**
     *
     * Sends `REQ_PRESET_SAVE`, then waits up to 1.5 s for the deferred save
     * to show in the directory. The mirror's active slot and occupied mask
     * follow, and the baseline becomes the live state (it now matches the
     * active preset). Runs under the Link device lock.
     *
     * Errors: [`DspiError::Refused`] with the `PRESET_*` status
     * (`PRESET_ERR_INVALID_SLOT` for a slot past 9, without sending);
     * [`DspiError::ReadOnly`] on a read-only connection;
     * [`DspiError::Disconnected`]; [`DspiError::Locked`] /
     * [`DspiError::Denied`] when the Link hub refuses its lock;
     * [`DspiError::Transfer`] when the device does not confirm in time (the
     * mirror then follows the directory, if it answers, and the baseline
     * stays); the transport's typed error when a transfer fails.
     */
    @Throws(DspiException::class)
    fun savePreset(slot: Int)

    /**
     * Load preset `slot` (0..10) and re-read every parameter into the
     * mirror.
     *
     * Sends `REQ_PRESET_LOAD`, waits up to 1.5 s for the device to report
     * the slot active, then re-reads the bulk image ([`DspiCore::refresh_params`]) and the
     * directory. The baseline becomes the loaded state. Runs under the Link
     * device lock. The device also notifies `PRESET_LOADED` and then
     * `BULK_INVALIDATED` (source `PRESET`); `process_notifications`
     * re-reads on those as on any foreign change.
     *
     * Errors: [`DspiError::Refused`] with the `PRESET_*` status;
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`];
     * [`DspiError::Locked`] / [`DspiError::Denied`];
     * [`DspiError::Transfer`] when the device does not confirm the load in
     * time (a load that failed on the device looks the same: the image is
     * not re-read, the active slot follows the directory if it answers, and
     * the baseline stays); the transport's typed error when a transfer, or
     * the re-read, fails.
     */
    @Throws(DspiException::class)
    fun loadPreset(slot: Int)

    /**
     * Copy the live state into preset `dest`, then save it back to
     * `source` so `source` stays the active slot (as the macOS Console
     * does). **Writes flash twice.**
     *
     * Each deferred save must finish (the device reports that slot active)
     * before the next is sent, or the second would replace the first's
     * pending save. The baseline becomes the live state. Runs under the
     * Link device lock.
     *
     * Errors: as [`DspiCore::save_preset`] for either slot, plus
     * [`DspiError::Transfer`] when the device does not confirm either save
     * in time (after the first, nothing is saved to `source`; `dest` may
     * hold the live state and the directory says which slot is active).
     */
    @Throws(DspiException::class)
    fun copyPreset(source: Int, dest: Int)

    /**
     * Delete preset `slot` (0..10) and its name. **Writes flash.**
     *
     * Waits up to 1.5 s for the slot to leave the directory. Deleting the
     * active slot makes the device apply its factory defaults, so the
     * image is then re-read (the baseline is kept: the live state matches
     * no preset). Runs under the Link device lock.
     *
     * Errors: [`DspiError::Refused`] with the `PRESET_*` status;
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`];
     * [`DspiError::Locked`] / [`DspiError::Denied`];
     * [`DspiError::Transfer`] when the device does not confirm in time (the
     * mirror's directory fields then follow the directory, if it answers,
     * and the name is kept); the transport's typed error when a transfer or
     * the re-read fails.
     */
    @Throws(DspiException::class)
    fun deletePreset(slot: Int)

    /**
     * Name preset `slot` (0..10): at most 31 bytes of UTF-8, cut at a
     * character boundary (and at an embedded NUL); an empty name clears it.
     * The mirror's `preset_names[slot]` follows.
     *
     * Errors: [`DspiError::InvalidArgument`] for a slot past 9;
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`]; the transport's
     * typed error when the transfer fails.
     */
    @Throws(DspiException::class)
    fun setPresetName(slot: Int, name: String)

    /**
     * Read the name of preset `slot` (0..10) into the mirror and return it.
     * Works on a read-only connection.
     *
     * Errors: [`DspiError::InvalidArgument`] for a slot past 9;
     * [`DspiError::Disconnected`]; the transport's typed error when the
     * read fails (an empty slot stalls; its mirrored name is cleared).
     */
    @Throws(DspiException::class)
    fun getPresetName(slot: Int): String

    /**
     * Read the preset directory (occupied slots, startup mode and slot,
     * active slot, the output-config and master-volume persistence modes)
     * into the mirror and return it. Works on a read-only connection.
     *
     * Errors: [`DspiError::Disconnected`]; the transport's typed error when
     * the read fails or the reply is shorter than 5 bytes.
     */
    @Throws(DspiException::class)
    fun getPresetDirectory(): PresetDirectory

    /**
     * Choose the preset loaded at boot: `mode` 0 = load `default_slot`,
     * 1 = the last active slot. The mirror follows.
     *
     * Errors: [`DspiError::InvalidArgument`] for a mode other than 0 or 1
     * or a slot past 9; [`DspiError::ReadOnly`];
     * [`DspiError::Disconnected`]; the transport's typed error when the
     * transfer fails.
     */
    @Throws(DspiException::class)
    fun setPresetStartup(mode: Int, defaultSlot: Int)

    /**
     * Save the live state to the active preset slot (`REQ_SAVE_PARAMS`,
     * deferred on the device). **Writes flash.** The baseline becomes the
     * live state. Runs under the Link device lock.
     *
     * Errors: [`DspiError::Refused`] with the `FLASH_*` status;
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`];
     * [`DspiError::Locked`] / [`DspiError::Denied`]; the transport's typed
     * error when the transfer fails.
     */
    @Throws(DspiException::class)
    fun saveParams()

    /**
     * Revert to saved: reload the active preset through the deferred,
     * S/PDIF-safe preset load ([`DspiCore::load_preset`] of the mirror's
     * `active_preset_slot`).
     *
     * Errors: as [`DspiCore::load_preset`], except that a refusal is
     * reported as [`DspiError::Refused`] with a `FLASH_*` status:
     * `FLASH_ERR_CRC` for a corrupt slot, `FLASH_ERR_WRITE` otherwise.
     */
    @Throws(DspiException::class)
    fun loadParams()

    /**
     * Restore the factory defaults (`REQ_FACTORY_RESET`, deferred on the
     * device). **Writes flash.** Waits 250 ms, then re-reads everything
     * ([`DspiCore::fetch_all`]); the baseline becomes the reset state.
     * Runs under the Link device lock.
     *
     * Errors: [`DspiError::Refused`] with the `FLASH_*` status;
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`];
     * [`DspiError::Locked`] / [`DspiError::Denied`]; the transport's typed
     * error when the transfer or the re-read fails.
     */
    @Throws(DspiException::class)
    fun factoryReset()

    /**
     * The live state now matches the active preset: remember its image as
     * the baseline for [`DspiCore::preset_dirty`] and
     * [`DspiCore::preset_changes`]. Without a device, or before an image
     * has been read, the baseline is cleared. Never fails.
     */
    fun captureBaseline()

    /**
     * Whether the live state differs from the baseline in anything a
     * preset holds: exactly when [`DspiCore::preset_changes`] is not
     * empty. False before any baseline. Never fails.
     */
    fun presetDirty(): Boolean

    /**
     * What differs from the baseline (the active preset), one sentence
     * each, worded as the macOS Console words it ("Preamp L: 0.0 dB →
     * -3.0 dB", "2 bands changed on Output 1"). The master volume counts
     * only in WITH_PRESET master-volume mode, the hardware wiring and the
     * limiters only in WITH_PRESET output-config mode, both judged by the
     * live mode. The user volume and the DAC mute are no preset change, as
     * on macOS. An input source goes by the user's name when it has one,
     * from the connection's cache, so this does no I/O. Empty before any
     * baseline. Never fails.
     */
    fun presetChanges(): List<String>

    /**
     * Hold the device lock across a flow of several calls, so another
     * session's commands answer `Locked` until [`DspiCore::device_lock_release`]
     * (DSPi Link spec 7.7; Swift's `acquireDeviceLock`). It lasts at most
     * `timeout_ms`, capped at 60 000 (the hub's cap): after that the hub and
     * the core count it as released. The core's own locked flows
     * (`save_preset`, `load_preset`, `save_output_config`, ...) run inside it
     * without asking the hub again. It is given back when the connection
     * closes or is replaced, a Link re-bind included. On USB, MIDI and the
     * demo device it succeeds at once, as their flows do. Blocking over
     * Link: call it off the UI thread.
     *
     * A call while the lock is already held keeps it as it is (no second
     * request, the same timeout) and makes it the caller's: an IR learn or
     * a firmware install no longer ends it.
     *
     * Errors: [`DspiError::InvalidArgument`] for a `timeout_ms` of 0;
     * [`DspiError::Disconnected`] with no device, or when the connection
     * changed while the hub was asked; [`DspiError::Locked`] when another
     * session holds it; [`DspiError::Denied`] for a viewer.
     */
    @Throws(DspiException::class)
    fun deviceLockAcquire(reason: String, timeoutMs: Long)

    /**
     * Release the device lock held past a call, whatever took it
     * ([`DspiCore::device_lock_acquire`], an IR learn, `enter_bootloader`).
     * Idempotent, and never blocks. A lock of a connection since closed
     * went with it.
     */
    fun deviceLockRelease()

    /**
     * One IN transfer: `opcode`, `value` as `wValue`, at most `len` bytes
     * back. The reply is returned as the device sent it, so it may be
     * shorter than `len`, and a status byte in it is not interpreted.
     *
     * An opcode that is not a plain read (`REQ_PRESET_LOAD`,
     * `REQ_RTA_CONTROL`, ...) is a write-as-read and is treated as a write.
     * A plain read is any `*_GET_*` opcode, `REQ_EXTENSION`, `REQ_LIMITER`,
     * `REQ_OUTPUT_LATENCY`, and the three §1.2 exceptions: `REQ_CLEAR_CLIPS`,
     * `REQ_RESET_BUFFER_STATS` and `REQ_ENTER_BOOTLOADER`.
     *
     * The mirror does not change here. A device change reaches it through
     * the notification, like anyone else's. Over DSPi Link the
     * `BULK_INVALIDATED` of a command of ours counts as our own echo and
     * does not re-read, so after a raw command that replaces many settings
     * (a preset load) call [`refresh_params`](Self::refresh_params) there.
     *
     * Blocks for the transfer with the core's lock held: call it off the UI
     * thread. `REQ_GET_ALL_PARAMS` for a whole image is the slow case.
     *
     * Errors: [`DspiError::InvalidArgument`] for `REQ_SET_ALL_PARAMS` and
     * the chunk opcodes (nothing is sent); [`DspiError::Disconnected`];
     * [`DspiError::ReadOnly`] for a write-as-read on a read-only connection
     * (nothing is sent); [`DspiError::Refused`] with status 0 when the
     * device stalls; [`DspiError::Denied`], [`DspiError::Locked`] or
     * [`DspiError::Transfer`] from the link.
     */
    @Throws(DspiException::class)
    fun rawGet(opcode: Int, value: Int, len: Int): List<Int>

    /**
     * One OUT transfer: `opcode`, `value` as `wValue`, `data` as the
     * payload. Success means the device took the transfer, not that it
     * applied the value; the firmware ignores some invalid ones.
     *
     * The mirror follows as for [`raw_get`](Self::raw_get). Blocks for the
     * transfer with the core's lock held: call it off the UI thread.
     *
     * Errors: [`DspiError::InvalidArgument`] for `REQ_SET_ALL_PARAMS`, the
     * chunk opcodes, an `EXT_CORE_VREG` request, or more than 65535 bytes of
     * `data` (nothing is sent);
     * [`DspiError::Disconnected`]; [`DspiError::ReadOnly`] on a read-only
     * connection (nothing is sent); [`DspiError::Refused`] with status 0
     * when the device stalls; [`DspiError::Denied`], [`DspiError::Locked`]
     * or [`DspiError::Transfer`] from the link.
     */
    @Throws(DspiException::class)
    fun rawSet(opcode: Int, value: Int, data: List<Int>)

    /**
     * Register (Some) or clear (None) the analyser wake-up listener. Once it
     * returns after None, no call is in progress (on another thread).
     * Replacing (Some -> Some) does not wait, and the old listener may then
     * be released on the RTA thread when its running call ends.
     *
     * The listener is called on the RTA worker thread (and once, for the
     * reset, on the thread that closes or replaces the device) without the
     * core lock held; it may read the core (`rta_get_snapshot`,
     * `get_state`) but must not block.
     */
    fun rtaSetListener(listener: RtaListener?)

    /**
     * Probe the open device's analyser and start polling it, on a worker
     * thread. Only on compatible firmware (a writable connection, PLAN
     * §1.5); a no-op without a device, on a read-only connection, or while
     * a worker was already started for this connection. The worker reads
     * the caps first (`rta_get_caps().supported` stays false on firmware
     * without an analyser) and ends on disconnect, on close and on reopen;
     * call this again after each connect.
     *
     * The worker holds a weak reference to the core for its per-poll lock.
     * Never fails: a worker thread that cannot be spawned is logged and the
     * analyser stays unsupported.
     */
    fun rtaStart()

    /**
     * What to analyse; mask 0 releases the analyser (the worker stops it
     * on the device). Kept across reconnects. Channel bits beyond the tap's
     * width are ignored; an `fft_order` of 0 means the device's default,
     * and one outside the device's range is clamped into it. Wakes the
     * worker at once.
     *
     * A request that changes what this console asks for takes the analyser
     * back from a console being followed ([`Self::rta_get_ownership`]).
     * Releasing it (mask 0) and asking for the same thing again does not.
     */
    fun rtaSetRequest(request: RtaRequest)

    /**
     * The device's analyser as the worker probed it: `supported` false
     * until then, and on firmware without one. `centres` has
     * `RTA_MAX_BANDS` entries, the first `max_bands` in Hz, the rest 0.
     */
    fun rtaGetCaps(): RtaCapsInfo

    /**
     * The latest picture and telemetry. `version` changes only when what is
     * drawn changed, `telemetry_version` when the status line did. Levels
     * are dBFS; a silent channel reads `RTA_FLOOR_DB`.
     */
    fun rtaGetSnapshot(): RtaSnapshot

    /**
     * Whether this console drives the analyser or follows another one's
     * configuration. While following, the snapshot shows the device's tap
     * and channels rather than the request's. The [`RtaListener`] is woken
     * when this changes.
     */
    fun rtaGetOwnership(): RtaOwnership

    /**
     * Stop following and push this console's own request on the next poll.
     * Wakes the worker at once; does nothing while already driving.
     */
    fun rtaTakeControl()

    /**
     * The generator's capabilities: the `REQ_SIGGEN_GET_CAPS` header and
     * each signal type's descriptor.
     *
     * Ok with `supported = false` when the firmware has no generator (the
     * header stalls, is short, or has another layout version). `types`
     * always has [`SIGGEN_TYPE_COUNT`] entries of 4 parameters each; the
     * first `type_count` (the device's count, clamped to 15) are the
     * device's, and one whose descriptor could not be read has id `0xFF`
     * (the host then uses its own table for that type).
     *
     * Errors: [`DspiError::Disconnected`]; another transfer failure of the
     * header (a timeout) as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun siggenFetchCaps(): SiggenCaps

    /**
     * The config the generator runs (or last ran), as the device sanitised
     * it. `p` has 4 entries.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall
     * (no generator) or a short reply as [`DspiError::Transfer`];
     * [`DspiError::Unsupported`] for a config of another layout version.
     */
    @Throws(DspiException::class)
    fun siggenGetConfig(): SiggenConfig

    /**
     * Stage a config (a running generator restarts with it, fading). The
     * device validates type, mask and parameters; it does not play it until
     * [`SIGGEN_CTL_START`](crate::consts::SIGGEN_CTL_START).
     *
     * Current firmware stalls on a refused config; older firmware ACKs even
     * a refused one over USB, so read it back with
     * [`siggen_get_config`](Self::siggen_get_config) to be sure.
     *
     * Errors: [`DspiError::InvalidArgument`] unless `p` has exactly 4
     * entries (nothing is sent); [`DspiError::ReadOnly`] on a read-only
     * connection; [`DspiError::Refused`] (status 0) when the device stalls;
     * [`DspiError::Disconnected`] or [`DspiError::Transfer`] otherwise.
     */
    @Throws(DspiException::class)
    fun siggenSetConfig(config: SiggenConfig)

    /**
     * Run a control action: `SIGGEN_CTL_START` plays the staged config,
     * `SIGGEN_CTL_STOP` fades out, `SIGGEN_CTL_STOP_NOW` cuts at once
     * ([`consts`](crate::consts)).
     *
     * Errors: [`DspiError::InvalidArgument`] for an action above 0xFF (the
     * firmware reads only the low byte; nothing is sent);
     * [`DspiError::ReadOnly`] on a read-only connection;
     * [`DspiError::Refused`] when the device refuses (an unknown action, or
     * START without a valid config: status 0 for a stall, else the status
     * byte); [`DspiError::Disconnected`] or [`DspiError::Transfer`]
     * otherwise.
     */
    @Throws(DspiException::class)
    fun siggenControl(action: Int)

    /**
     * What the generator is doing now: state (`SIGGEN_STATE_*`: idle, fade
     * in, run, gap, fade out), elapsed ms, cycles done, the last stop
     * reason (`SIGGEN_STOP_*`), the walked output (0xFF when not walking)
     * and the current sweep frequency (Hz, 0 when not sweeping).
     *
     * Errors: as [`siggen_get_config`](Self::siggen_get_config).
     */
    @Throws(DspiException::class)
    fun siggenGetStatus(): SiggenStatus

    /**
     * One `REQ_GET_STATUS` `u32` counter or reading (`STAT_*` in
     * [`consts`](crate::consts)); units per constant. Sub-queries the
     * firmware does not know answer 0.
     *
     * Errors: [`DspiError::InvalidArgument`] for sub-query 9 (the meter
     * block, read by `fetch_status`) and for 64 and above (the debug-build
     * loop profiler, whose reads change state), nothing sent; [`DspiError::Disconnected`]; a transfer failure
     * or short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchStat(which: Int): Long

    /**
     * The output rings' health (Output Ring Health in the Stats window), or
     * `None` on firmware without `REQ_OUTPUT_LATENCY` or with a short reply to
     * it: show no section then. Seven transfers.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, or a stall or a
     * short reply on a counter, as [`DspiError::Transfer`]. A counter that
     * cannot be read fails the call rather than reading as 0.
     */
    @Throws(DspiException::class)
    fun fetchRingHealth(): RingHealth?

    /**
     * The live outputs' fill for the Stats rows: to frame resolution, on the
     * ring's own scale, with the band around the live latency target. Firmware
     * without `REQ_OUTPUT_LATENCY` keeps its fixed scale and fixed bands. Two
     * transfers. Use this rather than [`BufferStats`]' percentages, whose
     * 48-frame steps read as an empty ring at the lowest latency.
     *
     * Errors: as for [`DspiCore::fetch_buffer_stats`].
     */
    @Throws(DspiException::class)
    fun fetchOutputFills(): List<OutputFill>

    /**
     * The Stats window's fast poll: the buffer fill levels and the live
     * outputs' fill, as [`DspiCore::fetch_buffer_stats`] and
     * [`DspiCore::fetch_output_fills`] give them, from one transfer.
     *
     * The fill target is kept on the connection. It is read again, for one more
     * transfer on the tick after, when this core changed the latency, when a
     * notification says the settings moved (a preset, a bulk write, a format
     * change, a lost packet), and after a Link re-attach. The firmware does not
     * notify a latency change, so another client's reaches this through
     * [`DspiCore::fetch_ring_health`]: call that on the slow cadence alongside.
     * While a change has yet to apply the target is read each tick.
     *
     * Errors: as for [`DspiCore::fetch_buffer_stats`]. A failed read of the
     * target is not an error: `fills` is `None`.
     */
    @Throws(DspiException::class)
    fun fetchStatsTick(): StatsTick

    /**
     * The buffer fill levels (%) and their watermarks
     * (`REQ_GET_BUFFER_STATS`, 44 bytes). `spdif` has 4 entries; the first
     * `num_spdif` (at most 4) are live.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchBufferStats(): BufferStats

    /**
     * Start the buffer watermarks again from now
     * (`REQ_RESET_BUFFER_STATS`). Diagnostics housekeeping that changes no
     * setting and nothing in the bulk image, so like `clear_clips` it is
     * allowed on a read-only connection (PLAN §1.2).
     *
     * Errors: [`DspiError::Refused`] for a status byte other than ACK (1);
     * [`DspiError::Disconnected`] or [`DspiError::Transfer`] otherwise.
     */
    @Throws(DspiException::class)
    fun resetBufferStats()

    /**
     * The S/PDIF receiver: lock state (0 inactive, 1 acquiring, 2 locked,
     * 3 relocking), input source, lock/loss counts, sample rate (Hz when
     * locked), parity errors, FIFO fill (%), and the receiver library's
     * debug state and callback counts (4 bits each).
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchSpdifRxStatus(): SpdifRxStatus

    /**
     * 24 bytes of IEC 60958 channel status of the locked S/PDIF input.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchSpdifRxChannelStatus(): List<Int>

    /**
     * GPIO of S/PDIF receiver `index` (0-3).
     *
     * Errors: [`DspiError::InvalidArgument`] for `index` 4 and above
     * (nothing sent); [`DspiError::Unsupported`] when the device has no
     * receiver `index` (it answers pin 0 for one it lacks; receiver 0
     * always exists, so its answer is passed on as is);
     * [`DspiError::Disconnected`]; a transfer failure as
     * [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchSpdifRxPin(index: Int): Int

    /**
     * The calibration flow as it stands, from memory: no traffic. It waits
     * for a poll or request in flight, so a slow link can hold it up as long
     * as that read: call it off the UI thread too.
     */
    fun coreVregCalView(): VregCalView

    /**
     * Read the device and advance the flow; never fails, the view says.
     * Call on every connect and about once a second while the page shows.
     * The only write that can go out is the next step of a run the user
     * started; never a `SET`, and none after the connection changed. Blocks
     * for a read: call it off the UI thread.
     */
    fun coreVregCalPoll(): VregCalView

    /**
     * Open the flow: the user reached it, from Advanced. Shows the warning
     * and what is on record; sends no write.
     *
     * `Disconnected`; `Unsupported` without a usable `EXT_CORE_VREG`;
     * `Denied` after a hub refused a write on this connection; `ReadOnly`;
     * `InvalidArgument` during a run.
     */
    @Throws(DspiException::class)
    fun coreVregCalOpen()

    /**
     * Close the flow: the user left. No traffic. `InvalidArgument` during a
     * run, which goes on until ended.
     */
    @Throws(DspiException::class)
    fun coreVregCalClose()

    /**
     * Start a run: the current record is cleared, `target` goes on trial
     * once the device shows that, and the soak counts for `soak_s` seconds.
     * `typed` is what the user typed when the view says this needs the word.
     *
     * `OvervoltWordRequired`, with no write, if it does and that is not
     * exactly the word. `InvalidArgument`, with no write, for a voltage
     * outside the build default to 1.25 V, a soak under the minimum, a trial
     * already running, or the wrong phase. `Disconnected`,
     * `Unsupported`, `ReadOnly`; `Refused`, `Denied`, `Locked`, `Transfer` for
     * the write, which is not retried.
     */
    @Throws(DspiException::class)
    fun coreVregCalStart(target: Int, soakS: Long, typed: String?)

    /**
     * Keep a trial found on the device: the soak counts from now, for
     * `soak_s` seconds. A trial outside the flow's range is left alone and
     * cannot pass. Sends nothing. Errors as for opening.
     */
    @Throws(DspiException::class)
    fun coreVregCalKeep(soakS: Long)

    /**
     * Save the voltage that passed, with a `SET`: the one explicit step from
     * a pass to flash. The status is read first, so a hang since the last
     * poll takes the pass back. Read back by later polls: `Committed` or
     * `VerifyFailed`. `typed` is the word when the view's `commit_needs_word`
     * says so, even if it was typed for the trial. A refusal leaves the flow in
     * `Passed`, with the trial running. Errors as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregCalCommit(typed: String?)

    /**
     * End a trial, or abort a run, with `TRIAL_END`, at any time but while a
     * save is being read back. Works without a fresh status, so a run can be
     * aborted while reads are failing. `Disconnected` and `ReadOnly` change
     * nothing. A write that fails otherwise is not retried: later polls end
     * in `Ended`, or in `VerifyFailed`, from which it can be asked for again.
     */
    @Throws(DspiException::class)
    fun coreVregTrialEnd()

    /**
     * Manual `SET` from the Advanced page. `value` 0 is the reset to the
     * build default; anything else has the flow's limits and confirmation.
     * Read back by later polls, as a commit. Errors as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualSet(value: Int, typed: String?)

    /**
     * Manual `TRIAL`, with the flow's limits and confirmation. It shows as a
     * found trial on the next poll. Errors as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualTrial(value: Int, typed: String?)

    /**
     * Manual `AUTO`: the firmware's automatic raising after repeated hangs.
     * Errors as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualAuto(on: Boolean)

    /**
     * Manual `CLEAR`: forget the hang count and the last trial failure.
     * `InvalidArgument` during a run, whose result it would erase. Errors
     * otherwise as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualClear()

    /**
     * Play an event on the demo device, for clients' tests and demo mode.
     * `seconds` is for [`VregDemoEvent::AdvanceUptime`]. `Unsupported`, with
     * no traffic, on anything but a simulated device.
     */
    @Throws(DspiException::class)
    fun coreVregDemoEvent(event: VregDemoEvent, seconds: Long)

    /**
     * The database at `db_path`: for the "Update Database" dialog. Reads the file.
     * Never fails: a file it cannot read is reported in
     * [`AutoEqDatabaseInfo::problem`].
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun autoeqDatabaseInfo(dbPath: String): AutoEqDatabaseInfo

    /**
     * Replace the database at `db_path` with an imported file's bytes, which the host
     * reads from its own file picker. Refused, with the file left alone, unless they
     * are a database with at least one profile: [`DspiError::AutoEq`] with code
     * `bad_content`, or [`DspiError::Io`] if the file cannot be written.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun autoeqImport(dbPath: String, data: List<Int>): AutoEqDatabaseInfo

    /**
     * Download a ready-made database from `url` and replace the one at `db_path`, once
     * it is known to be one. Blocks for the request. Errors as for [`autoeq_import`],
     * and [`DspiError::AutoEq`] with a fetch's code.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun autoeqUpdate(dbPath: String, url: String, fetch: AutoEqFetch): AutoEqDatabaseInfo

    /**
     * Reset to Built-in: remove the database at `db_path`, and reload the host's own
     * copy. True if there was one to remove.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun autoeqResetToBuiltin(dbPath: String): Boolean

    /**
     * What a rebuild will reach for and write, to show before starting one. Nothing
     * touches the network unless someone reads this and says yes.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun autoeqRebuildWarning(dbPath: String): String

    /**
     * Start rebuilding the database at `db_path` from the AutoEQ project on GitHub.
     * Returns at once. A full rebuild is thousands of requests, and unauthenticated
     * listings count against GitHub's limit of 60 an hour.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun autoeqRebuildStart(dbPath: String, fetch: AutoEqFetch): AutoEqRebuild

    /**
     * Magnitude in dB at one frequency (Hz) for a chain of bands.
     *
     * Bypassed and off bands are skipped; an empty chain is 0 dB. A total
     * power below -300 dB (a notch's exact zero) reads -300 dB.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun computeResponse(filters: List<FilterParams>, freq: Float): Float

    /**
     * 201-point magnitude curve, dB, on the [`curve_freq`] grid.
     *
     * Each band is designed once, then evaluated at every point. Same rules
     * as [`compute_response`].
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun computeMagnitudeCurve(filters: List<FilterParams>): List<Double>

    /**
     * 201-point phase curve in degrees on the same grid; continuous when
     * `unwrap`, else wrapped to ±180°.
     *
     * The unwrapped curve starts at the wrapped value of the first point and
     * then takes, between neighbours, the step in (-180°, 180°].
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun computePhaseCurve(filters: List<FilterParams>, unwrap: Boolean): List<Double>

    /**
     * Frequency (Hz) of curve point `i` (0..200): log-spaced, 10 Hz at 0,
     * 20 kHz at 200. A larger `i` extrapolates on the same spacing.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun curveFreq(i: Long): Double

    /**
     * Whether `map` (4 bytes, `DspState.crossfeed_pair_map` encoding) is a pair
     * map the firmware accepts for `num_pairs` stereo pairs (4 on RP2350, 2 on
     * RP2040): every pair gets two distinct non-PDM outputs, no output is used
     * twice, bytes beyond `num_pairs` are 0.
     *
     * Byte `p` is pair `p`: `0x00` is the default pairing (`2p`, `2p+1`), any
     * other value is `(right << 4) | left`. The non-PDM outputs are
     * `0..2 * num_pairs`. A map that is not exactly 4 bytes, or a `num_pairs`
     * of 0 or above 4, is invalid (false), never a panic.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun crossfeedPairMapValid(map: List<Int>, numPairs: Int): Boolean

    /**
     * Version facts of the linked core: this crate's version, the wire format
     * versions it reads and writes, the bulk image size and the curve size.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun coreInfo(): CoreInfo

    /**
     * Quantize a gain (dB) to 0.1 dB, as every gain setter does before sending
     * (the old core's `dsp_math::quantize_gain`, bit for bit).
     *
     * Rounds half away from zero (`f32::round` of `db * 10`), and maps -0.0
     * to +0.0 so a zero gain is never stored or sent as negative zero. It does
     * not clamp: callers clamp to the parameter's range first. NaN stays NaN
     * and ±inf stays ±inf (as does a finite value whose `* 10` overflows f32);
     * never panics.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun quantizeGain(db: Float): Float

    /**
     * Quantize a delay (ms) to 0.0001 ms, as the delay setters do before
     * sending (the old core's `dsp_math::quantize_delay`, bit for bit; the
     * Windows Console's step).
     *
     * Rounds half away from zero (`f32::round` of `ms * 10000`), and maps
     * -0.0 to +0.0. It does not clamp: callers clamp to `0..=max_delay_ms`
     * afterwards, as the old core did. NaN stays NaN and ±inf stays ±inf (as
     * does a finite value whose `* 10000` overflows f32); never panics.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun quantizeDelay(ms: Float): Float

    /**
     * Check a `.dspipreset` document and describe it, as JSON
     * `{ok, error, name, platform, firmware, savedUtc}` (`dspi_config_inspect`):
     * `ok` false with an `error` message for text that is not a document of
     * this schema (or is newer, or over [`MAX_FILE_BYTES`]). Needs no device.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun configInspect(text: String): String

    /**
     * Check a UF2 image: block structure, magic numbers, family id, the flash
     * range it covers, and the DSPi version string inside it. Never panics; a
     * refused image comes back with `valid == false` and the reason in
     * `problem` (fit for "This is not a firmware file: <problem>").
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun uf2Inspect(image: List<Int>): Uf2Info

    /**
     * Boards in BOOTSEL mode on the bus (USB `2E8A:0003` RP2040, `2E8A:000F`
     * RP2350). 0/0 where the bus cannot be enumerated (Android, and a build
     * without the `usb` feature: iOS).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun bootloaderCounts(): BootloaderCounts

    /**
     * Mounted bootloader drives (`INFO_UF2.TXT` at the root naming an RP2040 or
     * RP2350 boot ROM): Linux `/proc/self/mountinfo` + `/run/media`, macOS
     * `/Volumes`, Windows removable drives labelled `RPI-RP2` / `RP2350`.
     * Empty on Android.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun bootloaderDrives(): List<BootloaderDrive>

    /**
     * Write `image` to `drive` as `firmware.uf2`, synced to the medium.
     *
     * Before any byte goes out: the image is fully validated, the drive's
     * `INFO_UF2.TXT` is read again and must still name the board `drive`
     * describes, the image's family must be one that board boots, and the
     * drive must have room for the image. The file is then written with one
     * `write_all` and one `sync_all`.
     *
     * The board reboots into the new firmware as it takes the last block, so
     * the write or the sync can fail because the drive has gone: that (either
     * failed and the drive's `INFO_UF2.TXT` is no longer readable) counts as
     * success, logged at warn level. It cannot be told apart from a cable pulled mid-write, so
     * `Ok` means only "the write ended, or the drive went away during it, assumed
     * to be the board rebooting". **The caller must
     * confirm success** by waiting for the DSPi to re-enumerate and report the
     * image's version (`Uf2Info::firmware_version`); a timeout there is the
     * failure.
     *
     * The `INFO_UF2.TXT` re-check and the write are separate path-based
     * operations, so a different drive mounted at the same path in between
     * would get the file (an inherent check-then-use race; the Qt updater has
     * the same). The window is a few milliseconds and both boot ROMs reject an
     * image of the other family.
     *
     * Errors: [`DspiError::InvalidArgument`] for an invalid image, a drive that
     * is not a boot ROM's, or a family mismatch; [`DspiError::Io`] for a drive
     * that has gone, is short of space, or fails the write.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun flashToDrive(image: List<Int>, drive: BootloaderDrive)

    /**
     * The record for a board already in the bootloader: unknown, so the check
     * asks.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun firmwareGuardBoardInBootloader(): FirmwareGuardBoard

    /**
     * The guard (module docs). `typed_confirmation` is what the user typed, ""
     * if nothing yet; call again with it when the decision is
     * `NeedsConfirmation`. Pure and cheap enough for a UI thread's button, but
     * it does parse the whole image. Never panics.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun firmwareGuardCheck(image: List<Int>, board: FirmwareGuardBoard, typedConfirmation: String): FirmwareGuardVerdict

    /**
     * [`flash_to_drive`] behind the guard: the one to use wherever the core does
     * the writing. Nothing reaches the drive unless the verdict allows it.
     *
     * Errors: [`DspiError::FirmwareGuardBlocked`] with the guard's message when
     * the image needs confirmation; otherwise those of [`flash_to_drive`].
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun flashToDriveGuarded(image: List<Int>, drive: BootloaderDrive, board: FirmwareGuardBoard, typedConfirmation: String)

    /**
     * Parse a hub address typed by the user (`host`, `host:port`, `[v6]:port`).
     *
     * Errors: [`DspiError::InvalidArgument`] when it cannot be an address.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun linkParseAddress(text: String): LinkAddress

    /**
     * The WebSocket URL for a hub. An empty `path` is the default (`/dspi/v1`).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun linkWsUrl(host: String, port: Int, path: String): String

    /**
     * `GET /dspi/v1/info` (spec 3.2). Blocks up to a few seconds.
     *
     * Errors: [`DspiError::Link`] with `io` or `protocol`.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun linkFetchInfo(host: String, port: Int): LinkInfo

    /**
     * The wording of `phase`. `pin_source` is [`crate::LinkStatus::pin_source`]:
     * it matters only to [`LinkPhase::NeedsPairing`], and anything but `fixed`
     * means `window`, as a hub that does not say does (spec 7.2).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun linkPhaseText(phase: LinkPhase, pinSource: String): LinkPhaseText

    /**
     * The whole wording table: every key once, for a client's translation files.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun linkPhaseTexts(): List<LinkPhaseText>

    /**
     * The release notes for this build's platform: see the module docs.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun onboardingWhatsNewJson(): String

    /**
     * The Getting Started wizard's data for this build's platform: see the module
     * docs.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun onboardingGettingStartedJson(): String

    /**
     * The About table as a JSON document. `draft` is true until the owner approves
     * the wording:
     * `{draft, credit_lines: [{id, text}], makers: [{id, name, url, made}],
     * links: [{id, title, detail, url}], credits: [{id, name, what, url?}]}`.
     * `id`s are stable keys, as above. Show it as it is; it holds no legal text.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun aboutJson(): String
}
